import {
  RECOVERY_CAPTURE_KIND,
  RECOVERY_PROTOCOL_VERSION,
  recoveryExcludedScopes,
  recoveryIncludedScopes,
  type RecoveryCaptureHeader,
  type RecoveryPayloadInput,
} from "./recovery.ts";

export const recoveryGoldenHeader: RecoveryCaptureHeader = {
  captureId: "capture-0001",
  capturedAt: "2026-08-17T00:00:00.000Z",
  excludedScopes: [...recoveryExcludedScopes],
  formlessVersion: "0.1.17",
  includedScopes: [...recoveryIncludedScopes],
  kind: RECOVERY_CAPTURE_KIND,
  nativePayloadFormat: "formless.program.native",
  nativePayloadVersion: 47,
  sourceCursor: "cursor-0042",
  sourceOrigin: "https://example.com",
  version: RECOVERY_PROTOCOL_VERSION,
  workerVersion: "2026.08.17",
};

export const recoveryGoldenPayloadBytes = {
  media: new TextEncoder().encode("opaque media bytes"),
  program: Uint8Array.of(0x00, 0x01, 0x7f, 0x80, 0xff),
};

export function recoveryGoldenPayloads(): RecoveryPayloadInput[] {
  return [
    {
      byteLength: recoveryGoldenPayloadBytes.program.byteLength,
      bytes: [
        recoveryGoldenPayloadBytes.program.subarray(0, 2),
        recoveryGoldenPayloadBytes.program.subarray(2),
      ],
      id: "program:active",
      kind: "program",
    },
    {
      byteLength: recoveryGoldenPayloadBytes.media.byteLength,
      bytes: [recoveryGoldenPayloadBytes.media],
      id: "media:image:logo",
      kind: "media",
    },
  ];
}

